def semver_sort(versions):
    def parse(v):
        main = v.split('+', 1)[0]
        if '-' in main:
            core, pre = main.split('-', 1)
        else:
            core, pre = main, None
        parts = core.split('.')
        major, minor, patch = (int(p) for p in parts)
        if pre is None:
            pre_flag = 1
            pre_key = []
        else:
            pre_flag = 0
            idents = pre.split('.')
            pre_key = []
            for ident in idents:
                if ident.isdigit():
                    pre_key.append((0, int(ident)))
                else:
                    pre_key.append((1, ident))
        return (major, minor, patch, pre_flag, pre_key)

    indexed = list(enumerate(versions))
    indexed.sort(key=lambda pair: (parse(pair[1]), pair[0]))
    return [v for _, v in indexed]

